const $ = s => document.querySelector(s);
const PHOTO_COUNT = 35; // Photos du dossier : 1.jpg à 35.jpg.
const EXTENSIONS = ['jpg','jpeg','png','webp','JPG','JPEG','PNG','WEBP'];
let pages = [], current = 0, busy = false, opened = false;
const photoSources = new Map();
const surpriseState={step:'code',codeDraft:'',answerDraft:'',error:'',hint:false,choice:null};
const surpriseMarker='<div data-surprise-page></div>';
const escapeSurprise=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function surpriseAction(kind,value){
  if(kind==='code'&&surpriseState.step==='code'){
    if(String(value).trim()!=='071025'){surpriseState.error='Ce n’est pas le bon code… Essaie encore ❤';return false;}
    surpriseState.step='riddle';
  }else if(kind==='riddle'&&surpriseState.step==='riddle'){
    const answer=String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z]/g,'');
    if(!['amour','lamour','notreamour','cestlamour'].includes(answer)){surpriseState.error='Pas tout à fait… Pense à ce qui nous unit ❤';return false;}
    surpriseState.step='question';
  }else if(kind==='choice'&&surpriseState.step==='question'&&['public','private'].includes(value)){
    surpriseState.choice=value;surpriseState.step='done';
  }else return false;
  surpriseState.error='';return true;
}
function surpriseHTML(){
  let content='';
  const error=`<p class="surprise-error" role="status">${escapeSurprise(surpriseState.error)}</p>`;
  if(surpriseState.step==='code'){
    content=`<div class="num">Une dernière surprise</div><h2>Une page rien que pour toi</h2><p>Six chiffres pour ouvrir la suite de notre histoire.</p><form data-surprise-form="code"><label>Le code secret<input name="answer" type="password" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="off" required placeholder="••••••" value="${escapeSurprise(surpriseState.codeDraft)}"></label><button type="submit">Ouvrir la surprise</button>${error}</form>`;
  }else if(surpriseState.step==='riddle'){
    content=`<div class="num">Encore un petit mystère</div><h2>À toi de trouver…</h2><p class="riddle">Je ne sème pas de graines, pourtant je grandis quand on prend soin de moi. Je rapproche deux cœurs et je deviens plus fort quand on me partage. Qui suis-je ?</p><form data-surprise-form="riddle"><label>Ta réponse<input name="answer" type="text" maxlength="80" autocomplete="off" required value="${escapeSurprise(surpriseState.answerDraft)}"></label><button type="submit">Découvrir la suite</button>${error}</form><button class="surprise-hint" type="button" data-surprise-hint>Un petit indice ?</button>${surpriseState.hint?'<p class="hint-answer">Cinq lettres. Ça commence par A…</p>':''}`;
  }else if(surpriseState.step==='question'){
    content='<div class="num">Juste entre nous</div><h2>Une promesse…</h2><p class="surprise-promise">Sache que très bientôt, tu seras ma fiancée.</p><p>Réponds à cette question :</p><p class="surprise-question">En public ou en privé ?</p><div class="surprise-choices"><button type="button" data-surprise-choice="public">En public</button><button type="button" data-surprise-choice="private">En privé</button></div>';
  }else{
    content='<div class="num">Notre petit secret</div><h2>Dis-le-moi directement au pire :D</h2><p class="surprise-heart" aria-hidden="true">❤</p>';
  }
  return `<section class="surprise-panel" data-surprise-panel tabindex="-1">${content}</section>`;
}
function refreshSurprise(){
  const host=$('#right [data-surprise-page]');if(!host)return;
  host.innerHTML=surpriseHTML();
  host.querySelector('[data-surprise-panel]').focus({preventScroll:true});
}

const heading = (chapter,title) => `<div class="num">Chapitre ${chapter}</div><h2>${title}</h2>`;
const welcome = '<div class="home"><div class="big">💌</div><h2>Joyeux 1 an,<br>mon amour</h2><p>Une année entière écrite à deux.<br>Voici notre livre.</p><p>Tourne les pages…</p></div>';
const chapterPage = (number,title,note='') => `<div class="chapter-opening"><div class="chapter-ornament" aria-hidden="true">❦</div><div class="chapter-label">CHAPITRE ${number}</div><div class="chapter-rule"></div><h2>${title}</h2>${note?`<p class="chapter-note">${note}</p>`:''}<div class="chapter-heart" aria-hidden="true">❤</div></div>`;
function paginate(){
  const photosPerPage=window.innerHeight<520?1:2;
  document.documentElement.style.setProperty('--photos-per-page',photosPerPage);
  $('#letter-source').content.querySelector('[data-word-count]').textContent=WORDS.length;
  pages = [welcome, chapterPage(1,"Lettre d’amour")];
  const measure = document.createElement('div');
  measure.className = 'measure';
  measure.innerHTML = '<div class="paper-content"><div class="content-body"></div></div>';
  document.body.append(measure);
  const area = measure.querySelector('.content-body');
  const fits = () => area.scrollHeight <= area.clientHeight;
  const startLetter = () => {area.innerHTML = heading(1,"Lettre d’amour")+'<div class="letter"></div>';};
  startLetter();
  const paragraphs = $('#letter-source').content.querySelectorAll('p');
  paragraphs.forEach(source => {
    let paragraph = document.createElement('p');
    area.querySelector('.letter').append(paragraph);
    source.textContent.trim().split(/\s+/).forEach(word => {
      const before = paragraph.textContent;
      paragraph.textContent += (before ? ' ' : '') + word;
      if(!fits()){
        paragraph.textContent = before;
        if(!before) paragraph.remove();
        pages.push(area.innerHTML);
        startLetter();
        paragraph = document.createElement('p');
        paragraph.textContent = word;
        area.querySelector('.letter').append(paragraph);
      }
    });
  });
  pages.push(area.innerHTML);
  pages.push(chapterPage(2,`${WORDS.length} mots pour toi`,"(PS : J’ai passé 13 h non-stop à tout chercher dans le dictionnaire.)"));
  const startWords = () => {area.innerHTML = heading(2,`${WORDS.length} mots pour toi`)+'<div class="words-list"></div>';};
  startWords();
  WORDS.forEach((word,i) => {
    const span = document.createElement('span');span.className='word';span.style.setProperty('--w',i%70);
    const number = document.createElement('i');number.textContent = i+1;
    span.append(number,word);area.querySelector('.words-list').append(span);
    if(!fits()){span.remove();pages.push(area.innerHTML);startWords();area.querySelector('.words-list').append(span);}
  });
  pages.push(area.innerHTML);
  pages.push(chapterPage(3,'Nos souvenirs'));
  for(let i=1;i<=PHOTO_COUNT;i+=photosPerPage){
    let html=heading(3,'Nos souvenirs')+'<div class="photo-grid">';
    for(let n=i;n<=Math.min(i+photosPerPage-1,PHOTO_COUNT);n++) html+=`<figure class="polaroid"><button class="photo" data-photo="${n}" aria-label="Agrandir la photo ${n}" disabled><span aria-hidden="true">♡</span></button><figcaption>❤</figcaption></figure>`;
    pages.push(html+'</div>');
  }
  pages.push('<div class="home"><div class="big">❤</div><h2>À toutes les années<br>qui nous attendent.</h2><p>Je t’aime.</p></div>');
  pages.push(surpriseMarker);
  measure.remove();current=Math.min(current,pages.length-1);
}
function markup(index,anim=false){return `<div class="paper-content${anim?' settle':''}"><div class="content-body">${index<0?'<div class="home"><div class="big">❤</div><p>Toi & moi</p></div>':pages[index]}</div></div>${index<0?'':`<div class="page-number">${index+1}</div>`}`;}
function hydrate(root){
  root.querySelectorAll('[data-surprise-page]').forEach(host=>{host.innerHTML=surpriseHTML();});
  root.querySelectorAll('[data-photo]').forEach(button=>{
    const number=+button.dataset.photo;
    function show(src){if(!button.isConnected)return;const image=new Image();image.alt=`Notre souvenir ${number}`;image.src=src;button.replaceChildren(image);button.disabled=false;}
    if(photoSources.has(number)){show(photoSources.get(number));return;}
    let ext=0;const image=new Image();
    image.onload=()=>{photoSources.set(number,image.getAttribute('src'));show(image.getAttribute('src'));};
    image.onerror=()=>{if(++ext<EXTENSIONS.length)image.src=`photos/${number}.${EXTENSIONS[ext]}`;};
    image.src=`photos/${number}.${EXTENSIONS[0]}`;
  });
}
function controls(){ $('#previous').disabled=busy||current===0;$('#next').disabled=busy||current===pages.length-1;$('#position').textContent=`${current+1} / ${pages.length}`;$('.progress i').style.width=(current+1)/pages.length*100+'%'; }
function render(anim=false){ $('#right').innerHTML=markup(current,anim);$('#left').innerHTML=markup(current-1,anim);hydrate($('#right'));hydrate($('#left'));controls(); }
async function turn(direction){
  if(!opened||busy||current+direction<0||current+direction>=pages.length)return;
  busy=true;controls();
  const leaf=$('#leaf'),front=$('#leaf-front'),back=$('#leaf-back');
  const turningIndex=direction>0?current:current-1;
  front.innerHTML=markup(turningIndex);back.innerHTML=markup(turningIndex);
  hydrate(front);hydrate(back);
  if(direction>0){$('#right').innerHTML=markup(current+1,true);hydrate($('#right'));}
  else{$('#left').innerHTML=markup(current-2,true);hydrate($('#left'));}
  leaf.classList.add('moving');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const selectedSound=pickPageSound();
  const duration=reduced?1:Math.max(1050,selectedSound.duration*1000);
  playPageSound(selectedSound);
  const animations=[];
  try{
    const frames=pageMotionFrames(direction);
    const options={duration,easing:'linear',fill:'both'};
    animations.push(leaf.animate(frames.leaf,options));
    animations.push($('.shadow-right').animate(frames.right,options));
    animations.push($('.shadow-left').animate(frames.left,options));
    for(const [face,shading] of [[front,frames.front],[back,frames.back]]){
      const glaze=document.createElement('div');glaze.className='page-glaze';face.append(glaze);
      animations.push(glaze.animate(shading,options));
    }
    await animations[0].finished;
  }finally{
    current+=direction;busy=false;render();if(current===pages.length-1&&direction>0)burst();leaf.classList.remove('moving');
    animations.forEach(animation=>animation.cancel());front.replaceChildren();back.replaceChildren();
  }
}
// Même horloge pour l’angle, la projection de l’ombre et la lumière sur la feuille.
function pageMotionFrames(direction){
  const frames={leaf:[],left:[],right:[],front:[],back:[]};
  for(let i=0;i<=80;i++){
    const time=i/80;
    const eased=time*time*time*(time*(time*6-15)+10);
    const progress=direction>0?eased:1-eased;
    const angle=progress*Math.PI;
    const height=Math.sin(angle);
    // Projection du bord libre sous une lumière venant du haut à gauche.
    const projected=Math.cos(angle)+.28*height;
    const fade=Math.min(1,time*18,(1-time)*18);
    const opacity=fade*(.48-.2*height);
    const blur=1+height*13;
    frames.leaf.push({offset:time,transform:`rotateY(${-progress*180}deg)`});
    frames.right.push({offset:time,transform:`scaleX(${Math.max(.005,projected)})`,opacity:projected>0?opacity:0,filter:`blur(${blur}px)`});
    frames.left.push({offset:time,transform:`scaleX(${Math.max(.005,-projected)})`,opacity:projected<0?opacity:0,filter:`blur(${blur}px)`});
    frames.front.push({offset:time,opacity:height*.45});
    frames.back.push({offset:time,opacity:height*.32});
  }
  return frames;
}

async function openBook(){
  if(opened)return;
  opened=true;busy=true;unlockPageAudio();controls();
  const cover=$('#cover'),book=$('#book');
  const duration=matchMedia('(prefers-reduced-motion: reduce)').matches?1:1300;
  const keyboardOpening=document.activeElement===cover;
  let animation=null,fallback;
  cover.style.transition='none';
  book.classList.add('open');cover.disabled=true;
  try{
    animation=cover.animate([
      {transform:'rotateY(0deg)'},
      {transform:'rotateY(-180deg)'}
    ],{duration,easing:'cubic-bezier(.22,.61,.36,1)',fill:'forwards'});
    await Promise.race([
      animation.finished,
      new Promise(resolve=>{fallback=setTimeout(resolve,duration+200);})
    ]);
  }catch{/* Le livre reste accessible même si l’animation est interrompue. */}
  finally{
    clearTimeout(fallback);
    // Retirer définitivement la couverture du rendu : aucun plan ne reste devant le texte.
    cover.hidden=true;cover.setAttribute('aria-hidden','true');
    animation?.cancel();book.classList.add('fully-open');busy=false;render(true);
    $('.sound-controls').hidden=false;$('.navigation').hidden=false;controls();
    if(keyboardOpening)$('#next').focus({preventScroll:true});
  }
}
// Capture le clic sur toutes les surfaces, y compris les enfants de la couverture.
$('#book-stage').addEventListener('click',openBook,true);
$('#cover').onclick=openBook; // Conserve l’ouverture au clavier avec Entrée ou Espace.

$('#previous').onclick=()=>turn(-1);$('#next').onclick=()=>turn(1);
let photoTrigger=null;
function closePhoto(){ $('#lightbox').hidden=true;photoTrigger?.focus(); }
document.addEventListener('click',e=>{const button=e.target.closest('[data-photo]');if(button&&!button.disabled){photoTrigger=button;$('#lightbox img').src=button.querySelector('img').src;$('#lightbox').hidden=false;$('#close-photo').focus();}});
$('#close-photo').onclick=closePhoto;
$('#lightbox').onclick=e=>{if(e.target===$('#lightbox'))closePhoto();};
document.addEventListener('keydown',e=>{if(!$('#lightbox').hidden){if(e.key==='Escape')closePhoto();if(e.key==='Tab'){e.preventDefault();$('#close-photo').focus();}return;}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowRight'){e.preventDefault();turn(1);}if(e.key==='ArrowLeft'){e.preventDefault();turn(-1);}});
// Garder le passage lu lors d’un changement de taille ou d’orientation.
function readingAnchor(){
  const container=document.createElement('div');container.innerHTML=pages[current]||'';
  const word=container.querySelector('.word i');
  if(word)return{kind:'word',value:word.textContent};
  const photo=container.querySelector('[data-photo]');
  if(photo)return{kind:'photo',value:photo.dataset.photo};
  const letter=container.querySelector('.letter');
  if(letter)return{kind:'letter',value:letter.textContent.trim().split(/\s+/).slice(0,6).join(' ')};
  return{kind:'exact',value:pages[current]};
}
function repaginate(){
  const anchor=readingAnchor();paginate();
  const restored=pages.findIndex(html=>{
    if(anchor.kind==='exact')return html===anchor.value;
    const container=document.createElement('div');container.innerHTML=html;
    if(anchor.kind==='word')return Array.from(container.querySelectorAll('.word i')).some(el=>el.textContent===anchor.value);
    if(anchor.kind==='photo')return Array.from(container.querySelectorAll('[data-photo]')).some(el=>el.dataset.photo===anchor.value);
    return container.querySelector('.letter')?.textContent.replace(/\s+/g,' ').includes(anchor.value);
  });
  if(restored>=0)current=restored;render();
}
let resizeTimer;
function scheduleResize(){clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(document.activeElement?.matches('[data-surprise-form] input'))return;if(busy){scheduleResize();return;}repaginate();},180);}
window.addEventListener('resize',scheduleResize);
window.visualViewport?.addEventListener('resize',scheduleResize);
paginate();render();
document.fonts.ready.then(scheduleResize);
const glyphs=['❤','❤','♡','✦'];
for(let i=0;i<18;i++){const heart=document.createElement('span');const g=glyphs[i%glyphs.length];heart.textContent=g;if(g==='✦')heart.className='sp';heart.style.left=Math.random()*100+'%';heart.style.fontSize=10+Math.random()*24+'px';heart.style.animationDuration=(9+Math.random()*10)+'s,'+(4+Math.random()*4)+'s';heart.style.animationDelay=-Math.random()*15+'s';$('#hearts').append(heart);}
function burst(){
  if(reducedMotion.matches)return;
  for(let i=0;i<36;i++){const el=document.createElement('span');el.className='burst';el.textContent=i%4?'❤':'✦';el.style.left='50%';el.style.top='55%';el.style.fontSize=12+Math.random()*20+'px';document.body.append(el);
    const a=Math.random()*Math.PI*2,d=140+Math.random()*320;
    el.animate([{transform:'translate(-50%,-50%) scale(.3)',opacity:1},{transform:`translate(${Math.cos(a)*d}px,${Math.sin(a)*d-90}px) rotate(${Math.random()*360}deg) scale(1)`,opacity:1,offset:.6},{transform:`translate(${Math.cos(a)*d}px,${Math.sin(a)*d+120}px) scale(.8)`,opacity:0}],{duration:1800+Math.random()*900,easing:'cubic-bezier(.2,.7,.3,1)'}).finished.then(()=>el.remove(),()=>el.remove());}
}

// Le relief suit doucement la souris, indépendamment des feuilles qui tournent.
const stage = $('#book-stage');
const pointerIsFine = matchMedia('(hover: hover) and (pointer: fine)');
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
let targetTiltX=0, targetTiltY=0, tiltX=0, tiltY=0, tiltFrame=0;
function animateTilt(){
  tiltX+=(targetTiltX-tiltX)*.1;
  tiltY+=(targetTiltY-tiltY)*.1;
  const moving=Math.abs(targetTiltX-tiltX)+Math.abs(targetTiltY-tiltY)>.015;
  if(!moving){tiltX=targetTiltX;tiltY=targetTiltY;}
  stage.style.setProperty('--tilt-x',tiltX+'deg');
  stage.style.setProperty('--tilt-y',tiltY+'deg');
  stage.style.setProperty('--light-x',(50+tiltY*5)+'%');
  tiltFrame=moving?requestAnimationFrame(animateTilt):0;
}
function setTilt(x,y){targetTiltX=x;targetTiltY=y;if(!tiltFrame)tiltFrame=requestAnimationFrame(animateTilt);}
function resetTilt(){setTilt(0,0);}
window.addEventListener('pointermove',event=>{
  if(!pointerIsFine.matches||reducedMotion.matches||event.pointerType!=='mouse')return;
  if(!$('#lightbox').hidden){resetTilt();return;}
  const x=Math.max(-1,Math.min(1,event.clientX/window.innerWidth*2-1));
  const y=Math.max(-1,Math.min(1,event.clientY/window.innerHeight*2-1));
  setTilt(-y*4,x*6);
},{passive:true});
document.documentElement.addEventListener('pointerleave',resetTilt);
window.addEventListener('blur',resetTilt);
function motionPreferenceChanged(){
  if(tiltFrame)cancelAnimationFrame(tiltFrame);
  tiltFrame=0;tiltX=tiltY=targetTiltX=targetTiltY=0;
  stage.style.setProperty('--tilt-x','0deg');stage.style.setProperty('--tilt-y','0deg');
}
reducedMotion.addEventListener('change',motionPreferenceChanged);
pointerIsFine.addEventListener('change',motionPreferenceChanged);

// Les cinq froissements proviennent du MP3 fourni et sont lus localement.
let soundEnabled=true,activePageAudio=null,lastSoundIndex=-1;
let soundBag=[];
const pageSounds=[.84,1.13,1.15,1.48,.73].map((duration,index)=>{
  const audio=new Audio(`sons/page-${index+1}.mp3`);
  audio.preload='auto';audio.volume=.8;
  audio.setAttribute('playsinline','');
  return{audio,duration,index};
});
function unlockPageAudio(){
  // Précharger à l’ouverture ; play() est appelé directement au geste de lecture.
  pageSounds.forEach(({audio})=>{if(audio.readyState===0)audio.load();});
}
function pickPageSound(){
  if(!soundBag.length){
    soundBag=pageSounds.map((_,index)=>index);
    for(let i=soundBag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[soundBag[i],soundBag[j]]=[soundBag[j],soundBag[i]];}
    if(soundBag[soundBag.length-1]===lastSoundIndex){
      [soundBag[0],soundBag[soundBag.length-1]]=[soundBag[soundBag.length-1],soundBag[0]];
    }
  }
  const index=soundBag.pop();lastSoundIndex=index;return pageSounds[index];
}
function playPageSound(sound){
  if(!soundEnabled)return;
  try{
    if(activePageAudio){activePageAudio.pause();activePageAudio.currentTime=0;}
    const audio=sound.audio;activePageAudio=audio;
    audio.currentTime=0;audio.playbackRate=1;audio.volume=.8;
    const promise=audio.play();
    if(promise)promise.catch(()=>{});
  }catch{/* La lecture des pages reste disponible si le navigateur bloque le son. */}
}
$('#sound-toggle').onclick=()=>{
  soundEnabled=!soundEnabled;
  $('#sound-toggle').textContent=`Son des pages : ${soundEnabled?'activé':'coupé'}`;
  $('#sound-toggle').setAttribute('aria-pressed',String(soundEnabled));
  $('#sound-toggle').setAttribute('aria-label',soundEnabled?'Couper le bruit des pages':'Activer le bruit des pages');
  if(soundEnabled)unlockPageAudio();
  else if(activePageAudio){activePageAudio.pause();activePageAudio.currentTime=0;}
};

// Balayage tactile, en complément des boutons accessibles au pouce.
let swipeStart=null,blockPhotoClickUntil=0;
$('#book-stage').addEventListener('pointerdown',event=>{
  if(event.target.closest('input,form,[data-surprise-panel] button'))return;
  if(event.pointerType!=='touch'||!event.isPrimary||!opened||busy||!$('#lightbox').hidden)return;
  swipeStart={id:event.pointerId,x:event.clientX,y:event.clientY};
},{passive:true});
window.addEventListener('pointerup',event=>{
  if(!swipeStart||event.pointerId!==swipeStart.id)return;
  const dx=event.clientX-swipeStart.x,dy=event.clientY-swipeStart.y;
  swipeStart=null;
  if(Math.abs(dx)>=50&&Math.abs(dx)>Math.abs(dy)*1.4){
    blockPhotoClickUntil=performance.now()+400;turn(dx<0?1:-1);
  }
},{passive:true});
window.addEventListener('pointercancel',()=>{swipeStart=null;},{passive:true});
$('#book-stage').addEventListener('click',event=>{
  if(performance.now()<blockPhotoClickUntil){event.preventDefault();event.stopPropagation();}
},true);

// Toutes les étapes restent dans cette page : aucune réponse n’est envoyée.
document.addEventListener('input',event=>{
  const form=event.target.closest('#right [data-surprise-form]');if(!form)return;
  surpriseState[form.dataset.surpriseForm==='code'?'codeDraft':'answerDraft']=event.target.value;
});
document.addEventListener('focusout',event=>{if(event.target.matches('[data-surprise-form] input'))scheduleResize();});
document.addEventListener('submit',event=>{
  const form=event.target.closest('#right [data-surprise-form]');if(!form)return;
  event.preventDefault();if(busy)return;
  const success=surpriseAction(form.dataset.surpriseForm,form.elements.answer.value);
  refreshSurprise();if(success&&surpriseState.step==='question')burst();
});
document.addEventListener('click',event=>{
  if(busy)return;
  const hint=event.target.closest('#right [data-surprise-hint]');
  if(hint){surpriseState.hint=true;refreshSurprise();return;}
  const choice=event.target.closest('#right [data-surprise-choice]');
  if(choice&&surpriseAction('choice',choice.dataset.surpriseChoice)){refreshSurprise();burst();}
});

// ===== Introduction : choix du thème puis de la musique =====
// Place ton fichier dans le dossier « sons » sous le nom musique.mp3.
const MUSIC_SRC='sons/musique.mp3',MUSIC_VOLUME=.3;
const music=new Audio(MUSIC_SRC);
music.loop=true;music.preload='auto';music.volume=0;music.setAttribute('playsinline','');
let musicWanted=false,musicFrame=0;
function updateMusicButton(){
  const button=$('#music-toggle');
  button.textContent=`Musique : ${musicWanted?'activée':'coupée'}`;
  button.setAttribute('aria-pressed',String(musicWanted));
  button.setAttribute('aria-label',musicWanted?'Couper la musique':'Activer la musique');
}
function fadeMusic(target,duration=1800){
  cancelAnimationFrame(musicFrame);
  const from=music.volume,start=performance.now();
  const step=now=>{
    const t=Math.min(1,(now-start)/duration);
    music.volume=Math.max(0,Math.min(1,from+(target-from)*t));
    if(t<1)musicFrame=requestAnimationFrame(step);
    else if(target===0)music.pause();
  };
  musicFrame=requestAnimationFrame(step);
}
function setMusic(on){
  musicWanted=on;updateMusicButton();
  if(!on){fadeMusic(0,600);return;}
  try{
    const promise=music.play();
    const started=()=>fadeMusic(MUSIC_VOLUME);
    if(promise)promise.then(started).catch(()=>{musicWanted=false;updateMusicButton();});else started();
  }catch{musicWanted=false;updateMusicButton();}
}
$('#music-toggle').onclick=()=>setMusic(!musicWanted);

function applyTheme(theme){
  document.documentElement.dataset.theme=theme;
  $('meta[name=theme-color]').content=theme==='retro'?'#2e171c':'#240c16';
  document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));
  // La police change la hauteur du texte : on repagine une fois qu’elle est chargée.
  const loaded=document.fonts?.load?document.fonts.load("1rem 'Special Elite'"):Promise.resolve();
  Promise.resolve(loaded).catch(()=>{}).then(()=>scheduleResize());
}
function closeIntro(){
  const intro=$('#intro');
  intro.classList.add('leaving');
  document.body.classList.remove('intro');
  setTimeout(()=>{intro.hidden=true;},550);
}
document.body.classList.add('intro');
applyTheme('normal');
$('#intro').addEventListener('click',event=>{
  const theme=event.target.closest('[data-theme-choice]');
  if(theme){applyTheme(theme.dataset.themeChoice);return;}
  if(event.target.closest('#theme-next')){
    $('#step-theme').hidden=true;$('#step-music').hidden=false;
    $('#step-music [data-music-choice="yes"]').focus({preventScroll:true});return;
  }
  const choice=event.target.closest('[data-music-choice]');
  if(choice){setMusic(choice.dataset.musicChoice==='yes');closeIntro();}
});
$('#theme-next').focus({preventScroll:true});
